import { useIntl } from 'react-intl';

import { BigNumber, ChartHeader, ErrorMessage, Skeleton } from 'components';
import type { BigNumberData } from 'components/BigNumber/types';

import type { PortfolioCardData } from '../../types';
import {
  StyledPortfolioBigNumberCardBody,
  StyledPortfolioBigNumberCardRoot,
  StyledPortfolioChartHeaderAlignStart,
  StyledPortfolioKpiBigNumberShell,
} from './PortfolioBigNumberCard.styles';

const PORTFOLIO_BIG_NUMBER_CLASS = 'innovation-hub-portfolio-big-number-card';

const CHART_HEADER_CONFIG = {
  inline: 'horizontal' as const,
  type: 'large' as const,
};

export interface PortfolioBigNumberCardProps {
  card: PortfolioCardData;
  dataTestId?: string;
}

export const PortfolioBigNumberCard = ({
  card,
  dataTestId,
}: PortfolioBigNumberCardProps) => {
  const row: BigNumberData | undefined = card.data[0];
  const bigNumberData: BigNumberData[] = row ? [row] : [];

  const chartHeader = (
    <StyledPortfolioChartHeaderAlignStart>
      <ChartHeader
        title={card.header.title}
        measure={card.header.measure}
        period={card.header.period}
        config={CHART_HEADER_CONFIG}
        dataTestId={dataTestId ? `${dataTestId}-chart-header` : undefined}
      />
    </StyledPortfolioChartHeaderAlignStart>
  );

  return (
    <StyledPortfolioBigNumberCardRoot
      data-testid={dataTestId}
      data-variant="innovationHubPortfolioBigNumber"
    >
      <StyledPortfolioBigNumberCardBody>
        <StyledPortfolioKpiBigNumberShell>
          <BigNumber
            asCard={false}
            size="medium"
            spacing="loose"
            alignment="left"
            orientation="vertical"
            className={PORTFOLIO_BIG_NUMBER_CLASS}
            dataTestId={dataTestId ? `${dataTestId}-bignumber` : undefined}
            header={chartHeader}
            data={bigNumberData}
            emptyStateMessage={row ? undefined : '—'}
          />
        </StyledPortfolioKpiBigNumberShell>
      </StyledPortfolioBigNumberCardBody>
    </StyledPortfolioBigNumberCardRoot>
  );
};

export interface PortfolioBigNumbersProps {
  data: PortfolioCardData[];
  loading?: boolean;
  error?: Error | null;
}

export const PortfolioBigNumbers: React.FC<PortfolioBigNumbersProps> = ({
  data,
  loading,
  error,
}) => {
  const { formatMessage } = useIntl();
  if (error) {
    return <ErrorMessage dataTestId="innovation-portfolio-big-numbers-error" />;
  }

  if (loading) {
    return (
      <div
        data-testid="innovation-portfolio-big-numbers-loading"
        style={{ padding: '0 20px' }}
      >
        <Skeleton
          height="144px"
          width="100%"
          length={2}
          gap="medium"
          borderRadius="medium"
        />
      </div>
    );
  }

  if (data.length > 0) {
    return (
      <div
        data-testid="innovation-portfolio-big-numbers"
        style={{
          display: 'grid',
          width: '100%',
          minWidth: 0,
          boxSizing: 'border-box',
          gridTemplateColumns: 'repeat(2, minmax(0, 1fr))',
          alignItems: 'stretch',
          gap: '16px',
          padding: '0 20px',
        }}
      >
        {data.map((card) => (
          <PortfolioBigNumberCard
            key={card.id}
            card={card}
            dataTestId={`portfolio-kpi-${card.id}`}
          />
        ))}
      </div>
    );
  }

  return (
    <div
      data-testid="innovation-portfolio-big-numbers-empty"
      style={{ padding: '0 20px', color: '#5C5C5C', fontSize: '14px' }}
    >
      {formatMessage({
        id: 'Innovation.InnovationHub.Overview.Portfolio.emptyState',
      })}
    </div>
  );
};
